}

// commit allocates the one buffer every reservation points into.
func (a *sharedArena) commit() error {
	buf, err := a.dev.NewBuffer(int(a.next) * 4)
	if err != nil {
		return fmt.Errorf("kokoro: shared fp32 arena of %d MB: %w", a.next*4>>20, err)
	}
	a.buf = buf
	return nil
