#version 450

// The epilogue of one of the decoder's AdaIN residual blocks: add the second
// convolution's bias, add the shortcut, scale by 1/sqrt(2), and write into the
// *wider* row the next block reads (SPEECH.md T4c).
//
// The 1/sqrt(2) is not a detail. StyleTTS2's block is a variance-preserving
// average of its two branches rather than the plain residual add the
// generator's blocks use, and leaving it out makes the output grow by sqrt(2)
// a block — 4x over the four the decoder stacks.
//
// The destination stride is the point of the kernel. Every decode block is
// handed its own output *concatenated* with the phoneme residual and the two
// curves, and those 66 side channels are the same for all four blocks — so
// they are written once at upload into columns [dim, lda) of a [T, lda]
// arena, and each block's epilogue writes its 1024 columns beside them.
// The concatenation upstream does per block costs nothing here because it is
// a row stride.
//
// The grid is 2-D — a band of 256 channels by one frame — so the index
// decomposition is free at any channel count, which matters because the
// decoder's are 514, 1090, 1024 and 512.
//
//   pc.inOff   [T, dim] fp32, the second convolution's output
//   pc.aux0    [T, dim] fp32, the shortcut's
//   pc.outOff  [T, lda] fp32 destination
//   pc.wOff    [dim] bias, or NO_W
//   pc.dim     the block's output channel count
//   pc.lda     the destination row stride
//   pc.scale   the scale applied to the sum

#include "dit_common.glsl"

layout(local_size_x = 256) in;

void main() {
    uint c = gl_GlobalInvocationID.x;
    if (c >= pc.dim) {
        return;
    }
    uint t = gl_WorkGroupID.y;
    float v = act[pc.inOff + t * pc.dim + c] + act[pc.aux0 + t * pc.dim + c];
    if (pc.wOff != NO_W) {
        v += wbuf[pc.wOff + c];
    }
    act[pc.outOff + t * pc.lda + c] = v * uintBitsToFloat(pc.scale);
}
#version 450

#extension GL_EXT_shader_16bit_storage : enable
#extension GL_EXT_shader_explicit_arithmetic_types_float16 : enable

// The `pool` of the one decoder block that doubles its frame count: a
// *depthwise* transposed convolution, one tap group per channel, stride 2,
// kernel 3, padding 1, output padding 1 — the one combination that takes T
// frames to exactly 2T (SPEECH.md T4c).
//
// Depthwise means it is not a GEMM and does not want to be: each output
// channel reads only its own input channel, so the arithmetic is three
// multiplies a frame against a [T, C] tensor's worth of traffic. It is a
// scalar pass, and because the stride is 2 the residue decides which taps
// reach a frame at all:
//
//   j even   j = 2t + 1 - k  =>  k = 1,     one tap, from frame j/2
//   j odd                        k = 0, 2,  two taps, from (j+1)/2 and (j-1)/2
//
// There is no bounds check because there is a border: frame T of the source
// is a zero row the arena was allocated with, so the last output frame's
// missing tap reads a zero that was already there — dit_gemm.comp's A_CONV
// trick, one kernel over.
//
// The bias is applied here rather than dropped. The AdaIN that follows the
// convolution this feeds would remove a per-channel constant exactly, which
// is why `conv1`'s bias is not staged at all — but this one enters *before* a
// convolution whose zero padding makes its contribution differ on the two
// boundary frames, so it is not quite a constant and is kept.
//
//   pc.inOff   fp16 [T, lda] source, bordered
//   pc.outOff  fp16 [2T, lda] destination, bordered
//   pc.wOff    [C, 3] fp32 weights, tap fastest
//   pc.bOff    [C] fp32 bias, or NO_W
//   pc.dim     C
//   pc.lda     the row stride of both

#include "dit_common.glsl"

layout(binding = 2) buffer HAct { float16_t hact[]; };

layout(local_size_x = 256) in;

void main() {
    uint c = gl_GlobalInvocationID.x;
    if (c >= pc.dim) {
        return;
    }
    uint j = gl_WorkGroupID.y;
    float v = 0.0;
    if (pc.bOff != NO_W) {
        v = wbuf[pc.bOff + c];
    }
    uint w = pc.wOff + c * 3u;
    if ((j & 1u) == 0u) {
        v += wbuf[w + 1u] * float(hact[pc.inOff + (j >> 1u) * pc.lda + c]);
    } else {
        v += wbuf[w] * float(hact[pc.inOff + ((j + 1u) >> 1u) * pc.lda + c]);
        v += wbuf[w + 2u] * float(hact[pc.inOff + ((j - 1u) >> 1u) * pc.lda + c]);
    }
    hact[pc.outOff + j * pc.lda + c] = float16_t(v);
}
#version 450

#extension GL_KHR_shader_subgroup_basic : enable

// Per-channel sum and sum of squares over a chunk of frames, for the AdaIN
// that precedes every convolution in kokoro's vocoder (SPEECH.md T4).
//
// AdaIN normalises each *channel* over time — an instance norm, not a layer
// norm — so the reduction runs down a column of a channel-last [T, C]
// activation, which is the awkward direction. It is done anyway: holding the
// tensor channel-last is what makes the convolutions GEMMs (S7), and a
// reduction is one pass while a transpose would be two.
//
// The access is still coalesced, because the workgroup is laid out across
// *channels* rather than along the column: 256 threads cover 256/C row groups
// of C consecutive channels, so one wave's addresses are one contiguous run
// of a row. The column direction is the loop, not the lane index.
//
// One workgroup per chunk of frames; the partials are reduced by
// kokoro_affine.comp, which is what makes this parallel over a 15601-frame
// tensor instead of one workgroup per channel.
//
// NPOT is the same reduction over a channel count that is neither a power of
// two nor smaller than a workgroup -- kokoro's decoder normalises over 514,
// 1090, 1024 and 512 channels (SPEECH.md T4c). There the layout above has
// nothing to arrange: one workgroup of 256 threads is 256 *consecutive*
// channels of one row already, which is as coalesced as the generator's
// packing and needs no shared memory and no reduction at the end. The grid
// gains a second dimension, one band of 256 channels per y.
//
//   pc.inOff   [T, C] fp32 activations
//   pc.outOff  [chunks, 2C] fp32 partials: sums then sums of squares
//   pc.tokens  T
//   pc.dim     C, a power of two unless NPOT
//   pc.aux0    frames per chunk
//   pc.aux2    log2(C), unused when NPOT

#include "dit_common.glsl"

#ifndef NPOT
#define NPOT 0
#endif

#define NTHREADS 256
layout(local_size_x = NTHREADS) in;

#if NPOT
void main() {
    uint C = pc.dim;
    uint c = gl_WorkGroupID.y * NTHREADS + gl_LocalInvocationID.x;
    if (c >= C) {
        return;
    }
    uint t0 = gl_WorkGroupID.x * pc.aux0;
    uint t1 = min(t0 + pc.aux0, pc.tokens);

    float s = 0.0, q = 0.0;
    for (uint t = t0; t < t1; t++) {
        float v = act[pc.inOff + t * C + c];
        s += v;
        q += v * v;
    }
    act[pc.outOff + gl_WorkGroupID.x * 2u * C + c] = s;
    act[pc.outOff + gl_WorkGroupID.x * 2u * C + C + c] = q;
}
#else

shared float ssum[NTHREADS];
shared float ssq[NTHREADS];

void main() {
    uint C = pc.dim;
    uint tid = gl_LocalInvocationID.x;
    uint c = tid & (C - 1u);
    uint rg = tid >> pc.aux2;
    uint groups = uint(NTHREADS) >> pc.aux2;

    uint t0 = gl_WorkGroupID.x * pc.aux0;
    uint t1 = min(t0 + pc.aux0, pc.tokens);

    float s = 0.0, q = 0.0;
    for (uint t = t0 + rg; t < t1; t += groups) {
        float v = act[pc.inOff + t * C + c];
        s += v;
        q += v * v;
    }
    ssum[tid] = s;
    ssq[tid] = q;
    barrier();
    if (rg == 0u) {
        for (uint g = 1u; g < groups; g++) {
            s += ssum[(g << pc.aux2) + c];
            q += ssq[(g << pc.aux2) + c];
        }
        act[pc.outOff + gl_WorkGroupID.x * 2u * C + c] = s;
        act[pc.outOff + gl_WorkGroupID.x * 2u * C + C + c] = q;
    }
}
#endif
#version 450

// Reduce kokoro_stats.comp's partials into the per-channel affine an AdaIN
// applies, folding the style vector's gamma and beta into it.
//
// The whole of AdaIN is then two numbers per channel — a scale and a shift —
// and applying it is one fused elementwise pass (kokoro_act.comp). The style
// affine costs nothing per frame because it *is* per channel: `fc` is a
// [2C, 128] projection of one vector for the whole utterance, so the host
// computes gamma and beta once at upload and this pass never sees the style.
//
//   pc.inOff   [chunks, 2C] partials
//   pc.outOff  [2C] scale then shift
//   pc.wOff    [2C] gamma then beta, precomputed per utterance
//   pc.tokens  T, the divisor
//   pc.dim     C
//   pc.aux0    chunks
//   pc.eps     float bits

#include "dit_common.glsl"

layout(local_size_x = 256) in;

void main() {
    uint C = pc.dim;
    float n = float(pc.tokens);
    for (uint c = gl_LocalInvocationID.x; c < C; c += 256u) {
        float s = 0.0, q = 0.0;
        for (uint k = 0u; k < pc.aux0; k++) {
            s += act[pc.inOff + k * 2u * C + c];
            q += act[pc.inOff + k * 2u * C + C + c];
        }
        float mean = s / n;
        // E[x^2] - E[x]^2 rather than a second centred pass. The activations
        // here are post-convolution and mean-free to within their own scale,
        // so the cancellation is mild; TestGPUAdaIN bounds it against the
        // two-pass CPU reference rather than assuming it.
        float variance = max(q / n - mean * mean, 0.0);
        float inv = inversesqrt(variance + uintBitsToFloat(pc.eps));
        float scale = (1.0 + wbuf[pc.wOff + c]) * inv;
        act[pc.outOff + c] = scale;
        act[pc.outOff + C + c] = wbuf[pc.wOff + C + c] - mean * scale;
    }
}

