			t.Logf("%-22s relative %.3g", c.name, dv.Rel())
		}
	}
}

// TestGPUProsodyLadder measures every rung of the A_CONV=2 ladder over these
// stacks' shapes.
//
// The decoder's winner has no claim here and is not assumed to carry: its
// convolutions are M of 130 or 260 against N of 512 and 1024 at K = 3*1152,
// and these are the same M against N of 512 and 256 at K = 3*512 and 3*256 —
// a third of the K and a quarter of the output tile count, which is the
// regime where a rung's occupancy matters more than its K loop.
func TestGPUProsodyLadder(t *testing.T) {
	dev, done := newTestDevice(t)
	defer done()
	m := loadManifest(t)
	model := loadModel(t)
	shared := prosInputs(t, m)

	g := newProsody(t, dev, model, m, shared.Rows)
	defer g.Destroy()
	if err := g.Upload(shared); err != nil {
		t.Fatal(err)
	}
	want := refCurve(t, m, "f0_pred")

	for _, k := range ConvKernels() {
		if err := g.SetKernel(k); err != nil {
			t.Logf("%-20s unavailable: %v", k, err)
			continue
		}
		dis, _, err := g.graph()
		if err != nil {
			t.Fatal(err)
		}
		if _, err := vk.DispatchMultiTimed(dis, 1, 1, true); err != nil {
			t.Fatal(err)
		}
		best := time.Hour
		for r := 0; r < 5; r++ {
			t0 := time.Now()
			if _, err := vk.DispatchMultiTimed(dis, 1, 1, true); err != nil {
				t.Fatal(err)
			}
			if e := time.Since(t0); e < best {
				best = e
			}
		}
		got := g.abuf.ReadFloat32At(int(g.aOut[0]), g.OutFrames())
		dv := compare(t, got, want)
		t.Logf("%-20s %7.2f ms   relative %.3g", k, float64(best.Microseconds())/1000, dv.Rel())
		if dv.Rel() > prosTol {
			t.Errorf("%s: relative %.3g", k, dv.Rel())
		}
	}
}

// TestGPUProsodyProfile prints where the stacks' time goes, dispatch by
// dispatch, on GPU timestamps rather than wall clock.
func TestGPUProsodyProfile(t *testing.T) {
	dev, done := newTestDevice(t)
	defer done()
	m := loadManifest(t)
	model := loadModel(t)
	shared := prosInputs(t, m)

	g := newProsody(t, dev, model, m, shared.Rows)
	defer g.Destroy()
	if err := g.Upload(shared); err != nil {
		t.Fatal(err)
	}
	stages, err := g.Profile()
	if err != nil {
		t.Fatal(err)
	}
	kinds := map[string]float64{}
	var total float64
	for _, s := range stages {
		total += s.Time
		kind := s.Kind
		if i := indexByte(kind, ' '); i >= 0 {
			kind = kind[i+1:]
		}
		kinds[kind] += s.Time
	}
	for _, s := range stages {
		t.Logf("  %-24s %7.3f ms", s.Kind, s.Time*1000)
	}
	for k, v := range kinds {
		t.Logf("%-24s %7.3f ms  %4.1f%%", k, v*1000, 100*v/total)
	}
	t.Logf("%-24s %7.3f ms", "total", total*1000)
	if math.IsNaN(total) {
		t.Fatal("no timings")
	}
}

// TestGPUProsodyDurations runs the whole phoneme side both ways and checks
// that nothing the alignment depends on moved.
//
// T6a's lesson, one stage on: the tensor's relative error is not the thing to
// test, because the F0 curve drives a phase accumulator that reaches 1.3e5
// radians (T3) and tens of radians of phase decorrelate the samples while the
// sound is identical. What has to be bit-stable is the *alignment* — and the
// stacks run downstream of the durations, so the test is that they are still
// the same integers and that the curves they produce agree to a few parts in
// ten thousand.
func TestGPUProsodyDurations(t *testing.T) {
	dev, done := newTestDevice(t)
	defer done()
	m := loadManifest(t)
	model := loadModel(t)
	ids := m.InputIDs
	_, predStyle, err := model.Style(m.Voice, len([]rune(m.Phonemes)))
	if err != nil {
		t.Fatal(err)
	}

	host, err := model.Prosody(ids, predStyle, m.Speed)
	if err != nil {
		t.Fatal(err)
	}
	g := newProsody(t, dev, model, m, host.Frames)
	defer g.Destroy()
	model.ProsodyGPU = g
	defer func() { model.ProsodyGPU = nil }()

	got, err := model.Prosody(ids, predStyle, m.Speed)
	if err != nil {
		t.Fatal(err)
	}
	if got.Frames != host.Frames {
		t.Fatalf("%d frames on the device, %d on the host", got.Frames, host.Frames)
	}
	for i := range host.Durations {
		if got.Durations[i] != host.Durations[i] {
			t.Errorf("token %d: %d frames on the device, %d on the host",
				i, got.Durations[i], host.Durations[i])
		}
	}
	for _, c := range []struct{ name string; got, want []float32 }{
		{"f0", got.F0, host.F0},
		{"n", got.Energy, host.Energy},
	} {
		dv := compare(t, c.got, c.want)
		t.Logf("%-3s relative %.3g", c.name, dv.Rel())
		if dv.Rel() > prosTol {
			t.Errorf("%s: relative %.3g", c.name, dv.Rel())
		}
	}
	t.Logf("host %v, device %v (stacks %v against %v)",
		host.Times.Total(), got.Times.Total(), got.Times.Stacks, host.Times.Stacks)
	_ = fmt.Sprint()
}

