6	// One timestep of a bidirectional LSTM, both directions, in one dispatch
7	// (SPEECH.md T6c).
8	//
9	// # Why the recurrent half is all that is left here
10	//
11	// PyTorch computes a step as `W_ih x_t + W_hh h_{t-1} + b`. The first term
12	// does not depend on the state, so the whole sequence's worth of it is **one
13	// GEMM** — `[T, In] x [In, 8H]` with both directions' weights concatenated
14	// along N — done once before the loop starts, on the matrix cores, at the
15	// ladder's own shape. What is left for the sequential part is the second
16	// term, and that is the entire point of the split: `W_hh` is [H, 4H], half a
17	// megabyte in fp16, against `[W_ih | W_hh]`'s 1.8 — so the per-step B operand
18	// shrinks 3.5x and stays inside the MALL for every step of every LSTM in the
19	// model (research/5.1b: 805-965 GB/s resident against 236 from DRAM).
20	//
21	// # One dispatch a step, not three
22	//
23	// S8's transducer loop is `lstm_in`, a GEMM and `lstm_gate` per step, because
24	// its control flow is data-dependent and the host decides between them. Here
25	// nothing is decided: the sequence length is known before the first dispatch,
26	// so the whole recurrence is a static graph and the only cost per step is the
27	// dispatch itself. Three of those would be three barriers on the critical
28	// path of a chain 330 steps long, so the gates and the cell are fused into
29	// one.
30	//
31	// # The grid, and why it is not one workgroup
32	//
33	// A step is 0.5 MB of weights and 0.26 MFLOP of arithmetic — 500 bytes a
34	// FLOP, so it is a memory problem whatever else it looks like. The first
35	// version gave one workgroup to each direction and measured **14.3
36	// microseconds a step**, which is 36 GB/s: not the MALL's 805 and not even
37	// one CU's share of L2, but the latency of 1024 dependent loads per thread
38	// with eight waves to hide it.
39	//
40	// So the grid is (bands, directions) and a workgroup owns CELLS cells rather
41	// than all H of them: one thread to one **(cell, gate)** pair, a quarter of
42	// the loads each, and eight workgroups on eight CUs instead of two. The cell
43	// update then needs the four gates of a cell back in one place, which is the
44	// only barrier in the kernel.
45	//
46	// **The carried state has to be double-buffered for this.** With one
47	// workgroup a direction, a thread could overwrite `h[i]` once its own copy
48	// was in shared memory; with four, band 0 can finish and write `h[0..63]`
49	// before band 1 has read it, and there is no way to order two workgroups of
50	// one dispatch. So h alternates between two halves of the state region and
51	// `pc.aux2` says which is live. The cell state needs no such thing: cell i
52	// belongs to exactly one band for the whole sequence.
53	//
54	// `W_hh` is stored **k-major**, [H, 4H] rather than torch's [4H, H], so at
55	// reduction index k a wave's 32 threads read 32 consecutive halves. The
56	// transpose happens once at staging; the alternative is a 512-byte stride
57	// between neighbouring lanes on every one of 256 iterations.
58	//
59	// The two directions are one dispatch over `gl_WorkGroupID.y`. They are
60	// independent — forward reads token s, reverse reads T-1-s — and every offset
61	// that distinguishes them is a fixed stride from the other, so one set of
62	// push constants covers both.
63	//
64	//   pc.inOff   [T, lda] fp32, the input projections; direction d at column
65	//              d*4H, gates in torch's order: input, forget, cell, output
66	//   pc.lda     that row stride, 2*4H
67	//   pc.outOff  [T, ldb] fp32 output; direction d's h at column d*H
68	//   pc.ldb     that row stride, 2H
69	//   pc.aux0    fp32 state, 3H a direction: h, h again, then c
70	//   pc.aux1    the step index s, which is *not* the token index
71	//   pc.aux2    which half of the state h is live in, 0 or 1
72	//   pc.bOff    fp16 [2][H, 4H] k-major recurrent weights
73	//   pc.tokens  T
74	//   pc.dim     H, the hidden width per direction; a multiple of CELLS, at
75	//              most NTHREADS
76	
77	#include "dit_common.glsl"
78	
79	layout(binding = 3) readonly buffer W16 { float16_t w16[]; };
80	
81	// CELLS is how many cells one workgroup owns, and therefore NTHREADS/4 of
82	// them: four gates a cell, one thread each.
83	#ifndef CELLS
84	#define CELLS 64
85	#endif
86	// UNROLL is how many taps of the reduction a thread has in flight. The step
87	// is latency-bound rather than bandwidth-bound — see the grid note above —
88	// so this is the knob that matters and it is swept, not guessed.
89	#ifndef UNROLL
90	#define UNROLL 4
91	#endif
92	#define NTHREADS (CELLS * 4)
93	
94	layout(local_size_x = NTHREADS) in;
95	
96	// The carried state, read once at the top so the reduction never touches
97	// global memory for it, and the gate partials on the way back out.
98	shared float sh[256];
99	shared float gsum[NTHREADS];
100	
101	float sigmoid(float x) { return 1.0 / (1.0 + exp(-x)); }
102	
103	// tanh written out rather than called, for S8's reason: the built-in is free
104	// to evaluate (e^2x - 1)/(e^2x + 1), which overflows for a gate
105	// pre-activation of 90 or so, where folding the sign and using exp(-2|x|) is
106	// bounded everywhere and costs the same exponential.
107	float stable_tanh(float x) {
108	    float e = exp(-2.0 * abs(x));
109	    float t = (1.0 - e) / (1.0 + e);
110	    return x < 0.0 ? -t : t;
111	}
112	
113	void main() {
114	    uint d = gl_WorkGroupID.y;
115	    uint H = pc.dim;
116	    uint tid = gl_LocalInvocationID.x;
117	    uint gate = tid / uint(CELLS);
118	    uint lc = tid % uint(CELLS);
119	    uint cell = gl_WorkGroupID.x * uint(CELLS) + lc;
120	
121	    uint t = (d == 0u) ? pc.aux1 : (pc.tokens - 1u - pc.aux1);
122	    uint st = pc.aux0 + d * 3u * H;
123	    uint hIn = st + pc.aux2 * H;
124	    uint hOut = st + (1u - pc.aux2) * H;
125	    uint cOff = st + 2u * H;
126	
127	    for (uint k = tid; k < H; k += uint(NTHREADS)) {
128	        sh[k] = act[hIn + k];
129	    }
130	    barrier();
131	
132	    // One dot product: this gate of this cell against the whole state.
133	    float sum = act[pc.inOff + t * pc.lda + d * 4u * H + gate * H + cell];
134	    uint b = pc.bOff + d * H * 4u * H + gate * H + cell;
135	    uint row = 4u * H;
136	    for (uint k = 0u; k < H; k += uint(UNROLL)) {
137	        float v[UNROLL];
138	        for (int u = 0; u < UNROLL; u++) {
139	            v[u] = float(w16[b + uint(u) * row]);
140	        }
141	        for (int u = 0; u < UNROLL; u++) {
142	            sum += sh[k + uint(u)] * v[u];
143	        }
144	        b += uint(UNROLL) * row;
145	    }
146	    gsum[tid] = sum;
147	    barrier();
148	
149	    // The four gates of one cell are now CELLS apart in shared memory, and
150	    // the first CELLS threads own one cell each.
151	    if (tid >= uint(CELLS)) {
152	        return;
153	    }
154	    float gi = gsum[lc];
155	    float gf = gsum[uint(CELLS) + lc];
156	    float gg = gsum[2u * uint(CELLS) + lc];
157	    float go = gsum[3u * uint(CELLS) + lc];
158	
159	    float c = sigmoid(gf) * act[cOff + cell] + sigmoid(gi) * stable_tanh(gg);
160	    act[cOff + cell] = c;
161	    float h = sigmoid(go) * stable_tanh(c);
162	    act[hOut + cell] = h;
163	    act[pc.outOff + t * pc.ldb + d * H + cell] = h;
164	}

